"""T-020 phases on Kaggle T4x2 (run by the kernel generated by make_kernel_t020.py).

    t020_phases.py --phase gate                        # Phase 1: 40 gate problems -> stage1, stage3, math_gate
    t020_phases.py --phase new --half 0 --halves 2     # Phase 2: problems_new.jsonl[0::2] (stride split, keeps the level mix)

Per run dir R = /kaggle/working/T-020/<gate | new_h{half}of{halves}>:
  stage1_generations.jsonl, stage1_summary.jsonl, stage3_generations.jsonl, labels.jsonl[.parquet],
  token_stats.json (median tokens, hit-cap count, tok/s per stage), gate_report.json (gate only),
  problems_run.jsonl (the problems this kernel solved).
Resumable: the stage scripts skip keys already in *_generations.jsonl (append-only, one chunk per write).
Seeding: if an earlier kernel is attached via kernel_sources, its <run>/ *_generations.jsonl under /kaggle/input are copied in first.
"""
from __future__ import annotations

import argparse, glob, json, os, shutil, statistics, subprocess, sys, time
from pathlib import Path

OUT = Path("/kaggle/working/T-020")
M = "deepseek-ai/DeepSeek-R1-0528-Qwen3-8B"
RES = Path("results/grok/T-020")
BACKENDS = ["TRITON_ATTN", None, "FLEX_ATTENTION"]
TYPES = ["distract", "rename", "rephrase", "typos"]
T0 = time.time()


def log(*a):
    print(f"[{time.time() - T0:7.0f}s]", *a, flush=True)


def sh(cmd, env=None, timeout=None):
    log("$", " ".join(map(str, cmd)))
    try:
        return subprocess.run(list(map(str, cmd)), env={**os.environ, **(env or {})}, timeout=timeout).returncode
    except subprocess.TimeoutExpired:
        log("TIMEOUT"); return 124


def setup():
    OUT.mkdir(parents=True, exist_ok=True)
    rc = sh([sys.executable, "-m", "pip", "install", "-q", "vllm==0.31.0", "transformers==5.13.0",
             "pandas", "pyarrow", "scikit-learn"])
    # Kaggle image ships torchaudio built for cu128; vLLM 0.31 pulls torch cu130 -> transformers import fails.
    sh([sys.executable, "-m", "pip", "uninstall", "-y", "-q", "torchaudio"])
    env = subprocess.run([sys.executable, "-c", "import json,torch,vllm,transformers;print(json.dumps({'torch':torch.__version__,"
                          "'cuda':torch.version.cuda,'vllm':vllm.__version__,'transformers':transformers.__version__,"
                          "'gpus':[torch.cuda.get_device_name(i) for i in range(torch.cuda.device_count())]}))"],
                         capture_output=True, text=True)
    smi = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total,driver_version", "--format=csv"],
                         capture_output=True, text=True).stdout
    info = {"pip_rc": rc, "env": env.stdout.strip(), "env_err": env.stderr[-3000:], "nvidia_smi": smi}
    log("ENV", json.dumps(info)); (OUT / "env.json").write_text(json.dumps(info, indent=2))


def run_backend(script, args, tag, timeout):
    rec = OUT / "backend_used.json"
    used = json.loads(rec.read_text()) if rec.exists() else {}
    order = BACKENDS
    if "b" in used and used["b"] in BACKENDS:
        order = [used["b"]] + [b for b in BACKENDS if b != used["b"]]
    rc = 1
    for b in order:
        env = {"VLLM_ATTENTION_BACKEND": b} if b else {}
        left = None if timeout is None else max(60, timeout - (time.time() - T0))
        rc = sh([sys.executable, f"scripts/label_gen/{script}", "--backend", "vllm", "--model", M,
                 "--tensor-parallel-size", "2", "--dtype", "float16", *args], env=env, timeout=left)
        log(f"{tag} backend={b} rc={rc}")
        if rc == 0:
            rec.write_text(json.dumps({"b": b})); return rc
        if rc == 124:
            return rc  # hard stop: partial chunks are on disk
    return rc


def token_stats(R: Path) -> dict:
    out = {}
    for stage in ("stage1", "stage3"):
        g = R / f"{stage}_generations.jsonl"
        if not g.exists():
            continue
        recs = [json.loads(l) for l in g.read_text().splitlines() if l.strip()]
        if not recs:
            continue
        toks = [r["tokens"] for r in recs]
        chunks = {}  # one generate() call per chunk; every record in it carries the chunk's wall seconds
        for r in recs:
            chunks[(r["batch_seconds"], r["finished_at"][:16])] = r["batch_seconds"]
        sec = sum(chunks.values())
        out[stage] = {"n": len(recs), "tokens_total": sum(toks), "median_tokens": statistics.median(toks),
                      "mean_tokens": round(statistics.mean(toks), 1), "max_tokens": max(toks),
                      "n_hit_cap": sum(r["finish_reason"] == "length" for r in recs),
                      "hit_cap_rate": round(sum(r["finish_reason"] == "length" for r in recs) / len(recs), 4),
                      "gen_seconds": round(sec, 1), "tok_per_s": round(sum(toks) / sec, 1) if sec else None,
                      "n_chunks": len(chunks)}
    (R / "token_stats.json").write_text(json.dumps(out, indent=2))
    log("TOKEN_STATS", json.dumps(out))
    return out


def seed_from_inputs(run_name: str, R: Path):
    for f in ("stage1_generations.jsonl", "stage3_generations.jsonl"):
        dst = R / f
        for src in sorted(glob.glob(f"/kaggle/input/**/{run_name}/{f}", recursive=True)):
            if not dst.exists() or Path(src).stat().st_size > dst.stat().st_size:
                shutil.copy(src, dst); log("seeded", dst, "from", src)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--phase", choices=("gate", "new"), required=True)
    ap.add_argument("--half", type=int, default=0)
    ap.add_argument("--halves", type=int, default=1)
    ap.add_argument("--chunk-size", type=int, default=96)
    ap.add_argument("--hard-stop-h", type=float, default=float(os.environ.get("T020_HARD_STOP_H", "11.0")))
    a = ap.parse_args()
    hard = a.hard_stop_h * 3600
    sys.path.insert(0, "scripts/label_gen")
    from common import read_jsonl, write_jsonl
    setup()
    if a.phase == "gate":
        run, src = "gate", RES / "problems_gate.jsonl"
    else:
        assert 0 <= a.half < a.halves
        run, src = f"new_h{a.half}of{a.halves}", RES / "problems_new.jsonl"
    R = OUT / run; R.mkdir(parents=True, exist_ok=True)
    probs = read_jsonl(src)
    if a.phase == "new":
        probs = probs[a.half::a.halves]
    P = R / "problems_run.jsonl"; write_jsonl(P, probs)
    log(f"run {run}: {len(probs)} problems")
    seed_from_inputs(run, R)
    V = RES / "stage2_variants.jsonl"
    rc = run_backend("stage1_solve.py", ["--problems", P, "--out", R, "--samples", "5", "--max-new-tokens", "6144",
                                         "--min-base-acc", "0.5", "--chunk-size", a.chunk_size], "s1", hard)
    token_stats(R)
    if rc == 0:
        rc = run_backend("stage3_solve_variants.py", ["--problems", P, "--stage1", R / "stage1_summary.jsonl",
                         "--variants", V, "--out", R, "--samples", "4", "--max-new-tokens", "6144",
                         "--types", *TYPES, "--chunk-size", a.chunk_size,
                         "--source", "self-labelled (T-020 MATH rule variants)"], "s3", hard)
        token_stats(R)
    if rc == 0 and a.phase == "gate":
        # math_gate.py reads the full problems.jsonl (split / official_label) as the spec lists
        sh([sys.executable, "scripts/label_gen/math_gate.py", "--problems", RES / "problems.jsonl",
            "--variants", V, "--labels", R / "labels.jsonl", "--out", R])
    (R / "run_status.json").write_text(json.dumps({"run": run, "rc": rc, "wall_h": round((time.time() - T0) / 3600, 3),
                                                   "n_problems": len(probs)}, indent=2))
    log("DONE", run, "rc", rc)
    sys.exit(0 if rc == 0 else rc)


if __name__ == "__main__":
    main()
